// Open Mercato modular schema integration
import { createBusinessModule } from '@open-mercato/core';
export const ProcurementModule = createBusinessModule({
  name: 'procurement',
  entities: ['PurchaseOrder', 'Supplier', 'InvoiceAudit']
});

import { Mastra, Agent } from '@mastra/core';
export const eAgent = new Agent({
  name: 'procurement-auditor',
  instructions: 'Audit supplier invoices against PO records.',
  model: { provider: 'GOOGLE', name: 'gemini-2.0-flash' },
  tools: { verifyInvoice, checkStock }
});

import { CopilotKit } from '@copilotkit/react-core';
import { CopilotSidebar } from '@copilotkit/react-ui';

export function App() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit">
      <CopilotSidebar defaultOpen={true}>
        <Dashboard />
      </CopilotSidebar>
    </CopilotKit>
  );
}

import { StateGraph, END } from '@langchain/langgraph';
const workflow = new StateGraph(StateAnnotation)
  .addNode('auditInvoice', auditStep)
  .addNode('requireManagerApproval', approvalStep)
  .addEdge('auditInvoice', 'requireManagerApproval')
  .addEdge('requireManagerApproval', END);
export const graph = workflow.compile({ checkpointer: postgresCheckpointer });

import { Browser, Agent } from 'browser-use-pi';
const agent = new Agent({
  task: 'Log into NEWPAGES merchant portal and download latest orders CSV',
  llm: geminiModel
});
await agent.run();

import { AgentRuntime, defaultCharacter } from '@elizaos/core';
import { WhatsAppPlugin } from '@elizaos/plugin-whatsapp';
const runtime = new AgentRuntime({
  character: defaultCharacter,
  plugins: [WhatsAppPlugin]
});

import { FastMCP } from 'fastmcp';
import { z } from 'zod';
const server = new FastMCP({ name: 'e-business-tools' });
server.addTool({
  name: 'audit_invoice',
  parameters: z.object({ invoiceId: z.string(), poNumber: z.string() }),
  execute: async ({ invoiceId, poNumber }) => verifyInvoice(invoiceId, poNumber)
});
server.start({ transportType: 'stdio' });

import { Sandbox } from '@e2b/code-interpreter';
